#!/bin/bash
# Writes the header with the values compiled into a Sentry build (crash_report.mk): crash_report_header.sh <file>
# Reads SENTRY_DSN, SENTRY_ENVIRONMENT and FFS_GIT_SHA from the environment, so the DSN is never on a command line, and
# replaces <file> only when its content changes. Never commit the generated file.
set -euo pipefail

out="$1"
dsn="${SENTRY_DSN:-}"
environment="${SENTRY_ENVIRONMENT:-dev}"
# FFS_GIT_SHA empty (crash_report.mk exports it empty when not set): the short hash of this checkout's HEAD, or none outside a git
# checkout (release name "+dev")
sha="${FFS_GIT_SHA:-}"
[ -n "$sha" ] || sha="$(git -C "$(dirname "$0")" rev-parse --short=12 HEAD 2>/dev/null || true)"

# the values end up in C string literals: no quotes, backslashes, spaces or control characters, and a DSN-like URL;
# never print the DSN itself
if [[ "$dsn" == *[[:space:][:cntrl:]\"\\]* ]] || ! [[ "$dsn" =~ ^[A-Za-z][A-Za-z0-9+.-]*://[^/]+/.+$ ]]; then
    echo "error: SENTRY_DSN is empty or not a URL of the form https://<key>@<host>/<project> (without quotes, backslashes or spaces)" >&2
    exit 1
fi
[[ "$environment" =~ ^(dev|ci|release)$ ]] ||
    { echo "error: SENTRY_ENVIRONMENT must be dev, ci or release, not \"$environment\"" >&2; exit 1; }
[[ "$sha" =~ ^[0-9a-f]{0,40}$ ]] ||
    { echo "error: FFS_GIT_SHA must be a (short) commit hash, not \"$sha\"" >&2; exit 1; }

tmp="$out.tmp"
{
    echo '//generated by FreeFileSync/Source/crash_report_header.sh for a FFS_SENTRY=1 build: do not edit, never commit'
    echo '#pragma once'
    printf '#define ZEN_CRASH_REPORT_DSN "%s"\n' "$dsn"
    printf '#define ZEN_CRASH_REPORT_ENVIRONMENT "%s"\n' "$environment"
    printf '#define ZEN_CRASH_REPORT_GIT_SHA "%s"\n' "$sha"
} >"$tmp"
if cmp -s "$tmp" "$out"; then rm -f "$tmp"; else mv -f "$tmp" "$out"; fi
